using ModConfigEnhance.Overview;
using Newtonsoft.Json;
int count=0;void Check(bool ok,string message){if(!ok)throw new Exception(message);count++;}
string root=Path.Combine(AppContext.BaseDirectory,"s-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
var repo=new OverviewRepository(root);repo.Seed("1","2");repo.Migrate();Check(repo.IsProfileDirty,"legacy saved-only difference becomes dirty draft");Check(repo.DraftValue=="2"&&repo.SavedValue=="1","legacy goal kept while baseline reflects prior running profile");Check(!File.Exists(Path.Combine(root,"live.cfg")),"migration never writes live cfg");
var restored=new OverviewRepository(root);restored.Seed("1","2");restored.Restore();Check(restored.DraftValue=="2"&&restored.SavedValue=="1"&&restored.IsProfileDirty,"recovery survives restart with previous saved baseline");
restored.SetValue("1");restored.PersistRecoveryDraft();Check(!restored.RecoveryExists,"reverting to baseline removes old recovery file");
var pending=new OverviewRepository(Path.Combine(root,"pending"));pending.Seed("1","1");pending.AddPending("3");pending.Migrate();Check(pending.DraftValue=="3"&&pending.IsProfileDirty&&!pending.Pending,"legacy pending application becomes unsaved draft not auto apply");
var corrupt=new OverviewRepository(Path.Combine(root,"corrupt"));corrupt.Seed("1","1");corrupt.SetValue("2");corrupt.PersistRecoveryDraft();File.WriteAllText(Directory.GetFiles(Path.Combine(root,"corrupt","drafts"),"*.json").Single(),"broken json");corrupt.Restore();Check(corrupt.ReadWarning.Length>0&&corrupt.DraftValue=="2","corrupt recovery reports warning and preserves readable saved configuration");
corrupt.Discard();Check(!corrupt.RecoveryExists,"corrupt recovery can be explicitly discarded without blocking saved configuration");
var before=new OverviewState{pack=new(){name="old",author="original"},groups=new(){new(){id="a",name="A"}}};var edited=JsonConvert.DeserializeObject<OverviewState>(JsonConvert.SerializeObject(before))!;edited.pack.author="my author";var current=JsonConvert.DeserializeObject<OverviewState>(JsonConvert.SerializeObject(before))!;current.pack.name="new shared";current.groups.Add(new(){id="b",name="B"});var merged=SharedInformationRecovery.Merge(before,edited,current,out bool conflict);Check(merged.pack.name=="new shared"&&merged.pack.author=="my author"&&!conflict,"recovered information merges unrelated newer shared fields");Check(merged.groups.Count==2,"recovery preserves newly saved groups from another preset");edited.pack.name="my name";merged=SharedInformationRecovery.Merge(before,edited,current,out conflict);Check(conflict&&merged.pack.name=="my name","overlapping shared edits remain unsaved for explicit review");
var sharedRoot=Path.Combine(root,"shared");var prior=new OverviewRepository(sharedRoot);prior.Seed("1","1");prior.State.pack.name="old";prior._savedDraftProfile.state.pack.name="old";prior.State.pack.author="my author";prior.SetValue("2");prior.PersistRecoveryDraft();var latest=new OverviewRepository(sharedRoot);latest.Seed("1","1");latest.State.pack.name="new shared";latest._savedDraftProfile.state.pack.name="new shared";latest.Restore();Check(latest.State.pack.name=="new shared"&&latest.State.pack.author=="my author"&&latest.DraftValue=="2","actual draft restore rebases shared fields while retaining parameter and information edits");Check(latest._savedDraftProfile.state.pack.name=="new shared"&&latest._savedDraftProfile.state.pack.author=="","recovered dirty baseline uses latest shared generation");
latest.Discard();Check(latest.Profiles.Restores==0,"discarding ordinary recovery never rewrites a newer saved preset");var legacyDiscard=new OverviewRepository(Path.Combine(root,"legacy-discard"));legacyDiscard.Seed("1","2");legacyDiscard.Migrate();legacyDiscard.Discard();Check(legacyDiscard.Profiles.Restores==1,"explicit legacy migration can restore retained pre-save-only baseline on discard");
Console.WriteLine($"PASS {count} production legacy/recovery checks");
