namespace ModConfigEnhance.Overview{
internal static class GroupTree{internal static bool SupportedSchema(int version)=>version==1||version==2;}internal sealed class OverviewState{public OverviewPack pack=new();public List<OverviewGroup> groups=new();public List<OverviewModRule> mods=new();}internal sealed class OverviewPack{public string name="",author="";}internal sealed class OverviewGroup{public string id="",name="";}internal sealed class OverviewModRule{public string id="",alias="";}internal sealed class FakeProfiles{internal string AppliedId="p";internal int Restores;internal void RestoreBaseline(string id,OverviewProfile p){Restores++;}}
internal static class OverviewProfileStore{internal static T DeserializeJson<T>(string s)=>JsonConvert.DeserializeObject<T>(s)!;}
internal static class OverviewProfileExport{internal static string PortableId(string id)=>id;}
internal sealed partial class OverviewRepository{
internal string ProfileRuntimeDirectory,ViewedProfileId="p",ReadWarning="";internal bool _appliedView;internal FakeProfiles Profiles=new();internal OverviewState State=new();internal OverviewConfigSnapshot _draftConfig=new(),_editingRuntimeBaseline=new();internal List<OverviewProfileMod> _draftMods=new();internal OverviewProfile _savedDraftProfile=new(),_appliedSnapshot=new();internal string _savedDraftSignature="";internal PendingConfiguration _pendingConfiguration=new();internal OverviewProfile ViewedProfile=>new(){config=_draftConfig,mods=_draftMods};internal bool IsProfileDirty=>_savedDraftSignature!=DraftSignature(State,_draftConfig,_draftMods);internal string DraftValue=>_draftConfig.values.Single().serializedValue;internal string SavedValue=>_savedDraftProfile.config.values.SingleOrDefault()?.serializedValue??"";internal bool Pending=>_pendingConfiguration.pending;internal bool RecoveryExists=>File.Exists(RecoveryDraftPath);
internal OverviewRepository(string root){ProfileRuntimeDirectory=root;Directory.CreateDirectory(root);}static T Clone<T>(T value)=>JsonConvert.DeserializeObject<T>(JsonConvert.SerializeObject(value))!;static string DraftSignature(OverviewState s,OverviewConfigSnapshot c,IEnumerable<OverviewProfileMod> mods)=>JsonConvert.SerializeObject(c.values.Select(v=>v.serializedValue));static string PresetSignature(OverviewConfigSnapshot c,IEnumerable<OverviewProfileMod> m)=>JsonConvert.SerializeObject(c);internal static void AtomicWrite(string file,string s){Directory.CreateDirectory(Path.GetDirectoryName(file)!);File.WriteAllText(file,s);}internal void InvalidatePendingView(){}
