internal void Discard(){RestoreSavedDraftBaseline();ClearRecoveryDraft();}internal void Migrate()=>MigrateLegacyUnappliedDraft();internal void Restore()=>RestoreRecoveryDraft();internal void SetValue(string value)=>_draftConfig.values[0].serializedValue=value;internal void AddPending(string value){_pendingConfiguration.pending=true;_pendingConfiguration.config=Clone(_draftConfig);_pendingConfiguration.config.values[0].serializedValue=value;}
